import threading

def reproduce(connect, service) -> str | None:
    try:
        from psycopg.errors import DeadlockDetected
    except Exception:
        DeadlockDetected = None
    try:
        from service import InsufficientFunds
    except Exception:
        InsufficientFunds = Exception

    # Try up to 5 batches; break early on deadlock to keep test fast.
    # Each batch launches opposite transfers (1->2 and 2->1) at the same instant.
    for attempt in range(5):
        n_per_dir = 4
        n = n_per_dir * 2
        barrier = threading.Barrier(n)
        deadlocks = []
        errors = []

        def worker(frm, to):
            conn = connect()
            try:
                try:
                    barrier.wait(timeout=10)
                except Exception as e:
                    errors.append(e)
                    return
                try:
                    service.transfer(conn, frm, to, 1)
                except Exception as e:
                    # Count deadlocks (by type name or SQLSTATE)
                    is_deadlock = False
                    if DeadlockDetected is not None and isinstance(e, DeadlockDetected):
                        is_deadlock = True
                    elif e.__class__.__name__ == "DeadlockDetected":
                        is_deadlock = True
                    elif getattr(e, "sqlstate", None) == "40P01":
                        is_deadlock = True
                    elif "deadlock" in str(e).lower():
                        is_deadlock = True
                    if is_deadlock:
                        deadlocks.append(e)
                    elif isinstance(e, InsufficientFunds):
                        errors.append(e)
                    elif "insufficient" in str(e).lower():
                        errors.append(e)
                    else:
                        # Unexpected error (e.g. deadlock wrapped); treat deadlock-like as deadlock
                        errors.append(e)
            finally:
                try:
                    conn.close()
                except Exception:
                    pass

        threads = []
        for i in range(n_per_dir):
            threads.append(threading.Thread(target=worker, args=(1, 2)))
            threads.append(threading.Thread(target=worker, args=(2, 1)))
        for t in threads:
            t.start()
        for t in threads:
            t.join(timeout=20)

        if deadlocks:
            return f"deadlock: opposite transfers 1<->2 failed with deadlock detected ({len(deadlocks)} deadlocks in batch {attempt})"
    return None

