import psycopg


class InsufficientFunds(Exception):
    pass


def transfer(conn: psycopg.Connection, from_id: int, to_id: int, amount: int) -> None:
    with conn.transaction():
        if from_id == to_id:
            row = conn.execute(
                "SELECT balance FROM accounts WHERE id = %s FOR UPDATE", (from_id,)
            ).fetchone()
            if row is None:
                raise ValueError("unknown account")
            if row[0] < amount:
                raise InsufficientFunds(from_id)
            conn.execute("UPDATE accounts SET balance = balance - %s WHERE id = %s", (amount, from_id))
            conn.execute("UPDATE accounts SET balance = balance + %s WHERE id = %s", (amount, to_id))
            return
        first, second = (from_id, to_id) if from_id < to_id else (to_id, from_id)
        row_first = conn.execute(
            "SELECT balance FROM accounts WHERE id = %s FOR UPDATE", (first,)
        ).fetchone()
        row_second = conn.execute(
            "SELECT balance FROM accounts WHERE id = %s FOR UPDATE", (second,)
        ).fetchone()
        if row_first is None or row_second is None:
            raise ValueError("unknown account")
        if first == from_id:
            sender = row_first
        else:
            sender = row_second
        if sender[0] < amount:
            raise InsufficientFunds(from_id)
        conn.execute("UPDATE accounts SET balance = balance - %s WHERE id = %s", (amount, from_id))
        conn.execute("UPDATE accounts SET balance = balance + %s WHERE id = %s", (amount, to_id))
